/* ---------- utilitas ---------- */
const fm = (s) =>
  String(s).replace(/\^\{([^}]*)\}/g, "<sup>$1</sup>").replace(/_\{([^}]*)\}/g, "<sub>$1</sub>");
const nf = (x, d = 3) => (isFinite(x) ? Number(x).toFixed(d).replace(".", ",") : "–");
const pnum = (s) => parseFloat(String(s).trim().replace(",", "."));
const rnd = (n) => Math.floor(Math.random() * n);
const pick = (a) => a[rnd(a.length)];
function shuffle(a) {
  // Fisher-Yates
  const r = a.slice();
  for (let i = r.length - 1; i > 0; i--) {
    const j = rnd(i + 1);
    [r[i], r[j]] = [r[j], r[i]];
  }
  return r;
}
function M({ t, as: Tag = "span", ...rest }) {
  return <Tag {...rest} dangerouslySetInnerHTML={{ __html: fm(t) }} />;
}

