    x.fillStyle = C.navy; x.font = "600 30px " + SANS; x.fillText("UNIVERSITAS 17 AGUSTUS 1945 SURABAYA", W / 2, 330);
    x.font = "400 26px " + SANS; x.fillStyle = "#4a5470"; x.fillText("Program Studi S1 Teknik Elektro · Mata Kuliah Integral Diferensial", W / 2, 370);
    x.fillStyle = C.navy; x.font = "700 76px " + SERIF; x.fillText("SERTIFIKAT", W / 2, 480);
    x.fillStyle = "#4a5470"; x.font = "400 28px " + SANS; x.fillText("Diberikan kepada", W / 2, 540);
    let fs = 64; x.fillStyle = C.navy; x.font = "700 " + fs + "px " + SERIF; while (x.measureText(name || "Nama Mahasiswa").width > W - 300 && fs > 30) { fs -= 2; x.font = "700 " + fs + "px " + SERIF; }
    x.fillText(name || "Nama Mahasiswa", W / 2, 625);
