function canvasPdf(canvas) {
  const b64 = canvas.toDataURL("image/jpeg", 0.93).split(",")[1], bin = atob(b64), img = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) img[i] = bin.charCodeAt(i);
  const enc = (t) => { const u = new Uint8Array(t.length); for (let i = 0; i < t.length; i++) u[i] = t.charCodeAt(i) & 255; return u; };
  const chunks = [], offs = []; let len = 0;
  const add = (u) => { chunks.push(u); len += u.length; };
  const obj = (n, head, body) => { offs[n] = len; add(enc(n + " 0 obj\n" + head)); if (body) { add(enc("stream\n")); add(body); add(enc("\nendstream")); } add(enc("\nendobj\n")); };
  add(enc("%PDF-1.4\n"));
  const content = enc("q 842 0 0 595 0 0 cm /Im0 Do Q");
  obj(1, "<< /Type /Catalog /Pages 2 0 R >>");
  obj(2, "<< /Type /Pages /Kids [3 0 R] /Count 1 >>");
  obj(3, "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /XObject << /Im0 5 0 R >> >> /Contents 4 0 R >>");
  obj(4, "<< /Length " + content.length + " >>\n", content);
  obj(5, "<< /Type /XObject /Subtype /Image /Width " + canvas.width + " /Height " + canvas.height + " /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length " + img.length + " >>\n", img);
  const xr = len; let t = "xref\n0 6\n0000000000 65535 f \n";
  for (let n = 1; n <= 5; n++) t += String(offs[n]).padStart(10, "0") + " 00000 n \n";
  add(enc(t + "trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n" + xr + "\n%%EOF"));
  return new Blob(chunks, { type: "application/pdf" });
}
function savePdf(canvas, name, setMsg) {
  try {
    const url = URL.createObjectURL(canvasPdf(canvas)), a = document.createElement("a");
    a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 4000);
    setMsg("Berkas PDF sedang diunduh. Bila tidak terunduh, buka aplikasi ini di tab browser sendiri lalu coba lagi.");
  } catch (e) { setMsg("PDF gagal dibuat di lingkungan ini. Gunakan tombol Unduh PNG atau buka aplikasi di tab browser sendiri."); }
}
const predikat = (n) => (n >= 90 ? "Sangat Baik" : n >= 80 ? "Baik" : n >= PASS ? "Cukup" : "Belum Lulus");

function SertNilai({ prog, info, setInfo, go }) {
  const cv = useRef(null), logo = useRef(null);
  const [made, setMade] = useState(false), [msg, setMsg] = useState("");
  const hist = prog.hist || [];
  const draw = (name, nim) => {
    const c = cv.current; if (!c) return; const W = 1600, H = 1131; c.width = W; c.height = H; const x = c.getContext("2d"); const L = logo.current;
    const ok = L && L.complete && L.naturalWidth;
    x.fillStyle = "#fbf9f1"; x.fillRect(0, 0, W, H);
    if (ok) { x.save(); x.globalAlpha = 0.11; const s = 640, r = L.naturalHeight / L.naturalWidth; x.drawImage(L, W / 2 - s / 2, H / 2 - (s * r) / 2 + 20, s, s * r); x.restore(); }
    x.strokeStyle = C.navy; x.lineWidth = 14; x.strokeRect(40, 40, W - 80, H - 80); x.strokeStyle = C.gold; x.lineWidth = 4; x.strokeRect(68, 68, W - 136, H - 136);
    x.textAlign = "center";
    if (ok) { const s = 120, r = L.naturalHeight / L.naturalWidth; x.drawImage(L, W / 2 - s / 2, 100, s, s * r); }
    x.fillStyle = C.navy; x.font = "600 28px " + SANS; x.fillText("UNIVERSITAS 17 AGUSTUS 1945 SURABAYA", W / 2, 270);
    x.font = "400 24px " + SANS; x.fillStyle = "#4a5470"; x.fillText("Program Studi S1 Teknik Elektro · Mata Kuliah Integral Diferensial", W / 2, 308);
    x.fillStyle = C.navy; x.font = "700 62px " + SERIF; x.fillText("SERTIFIKAT NILAI KUIS", W / 2, 392);
    x.fillStyle = "#4a5470"; x.font = "400 26px " + SANS; x.fillText("Menerangkan bahwa", W / 2, 440);
    let fs = 56; x.fillStyle = C.navy; x.font = "700 " + fs + "px " + SERIF; while (x.measureText(name || "Nama Mahasiswa").width > W - 300 && fs > 30) { fs -= 2; x.font = "700 " + fs + "px " + SERIF; }
    x.fillText(name || "Nama Mahasiswa", W / 2, 508);
    x.fillStyle = C.gold; x.fillRect(W / 2 - 240, 528, 480, 3);
    x.fillStyle = "#4a5470"; x.font = "400 26px " + SANS; x.fillText("NIM " + (nim || "–") + " · memperoleh nilai kuis akhir modul", W / 2, 572);
    x.fillStyle = C.navy; x.font = "600 34px " + SERIF; x.fillText("Turunan Fungsi Eksponensial dan Logaritma", W / 2, 620);
    // score box
    const best = prog.best, lulus = best >= PASS, bx = W / 2 - 170, by = 645, bw = 340, bh = 130;
    x.fillStyle = "#fff"; x.fillRect(bx, by, bw, bh); x.strokeStyle = C.gold; x.lineWidth = 3; x.strokeRect(bx, by, bw, bh);
    x.fillStyle = C.navy; x.font = "700 92px " + SERIF; x.fillText(String(best), W / 2 - 22, by + 92);
    x.font = "400 34px " + SANS; x.fillStyle = "#4a5470"; x.textAlign = "left"; x.fillText("/ 100", W / 2 + 62, by + 92);
    x.textAlign = "center"; x.font = "600 24px " + SANS; x.fillStyle = lulus ? "#1d6b3a" : "#9b2c2c"; x.fillText("Nilai terbaik" + (lulus ? " · predikat " + predikat(best) : "") + " · " + (lulus ? "LULUS" : "BELUM LULUS"), W / 2, by + bh + 38);
    // history
    x.fillStyle = "#4a5470"; x.font = "400 24px " + SANS;
    const rows = hist.map((v, i) => "Percobaan " + (i + 1) + ": " + v + " (" + v / 10 + " dari 10 benar)").join("   ·   ");
    x.fillText(rows || "Belum ada percobaan", W / 2, 870);
    x.fillText("Batas kelulusan " + PASS + " · Soal acak 10 dari bank 18 soal · Kesempatan maksimal " + MAX_ATTEMPTS + " kali", W / 2, 910);
    const tgl = new Date().toLocaleDateString("id-ID", { day: "numeric", month: "long", year: "numeric" });
    x.font = "400 24px " + SANS; x.fillText("Surabaya, " + tgl, W / 2, 975);
    x.font = "400 20px " + SANS; x.fillText("Kode verifikasi: " + hash("N|" + name + "|" + nim + "|" + hist.join(",") + "|" + tgl), W / 2, 1020);
    x.font = "italic 18px " + SANS; x.fillStyle = "#7a8299"; x.fillText("Dibuat secara mandiri oleh aplikasi pembelajaran ini berdasarkan hasil kuis mahasiswa.", W / 2, 1058);
  };
  useEffect(() => { const im = new Image(); im.onload = () => { logo.current = im; if (made) draw(info.name, info.nim); }; im.src = LOGO_SRC; logo.current = im; /* eslint-disable-next-line */ }, []);
  if (!prog.attempts || !hist.length) return <div className="card stack"><h2>Sertifikat nilai kuis</h2><p>Sertifikat nilai dapat dibuat setelah Anda menyelesaikan minimal satu percobaan kuis.</p><button className="btn" onClick={() => go("kuis")}>Ke halaman kuis</button></div>;
  const make = () => { draw(info.name.trim(), info.nim); setMade(true); setMsg("Periksa nama dan NIM pada gambar, lalu unduh PDF."); };
  const png = () => { try { const a = document.createElement("a"); a.href = cv.current.toDataURL("image/png"); a.download = "Nilai_Kuis_" + (info.nim || "mhs") + ".png"; document.body.appendChild(a); a.click(); a.remove(); } catch (e) { setMsg("Tekan lama atau klik kanan pada gambar untuk menyimpannya."); } };
  return (
    <div className="stack"><section className="card stack"><h2>Sertifikat nilai kuis</h2><p style={{ margin: 0 }}>Nilai terbaik Anda <b>{prog.best}</b> dari 100 ({predikat(prog.best)}). Sertifikat ini memuat nilai terbaik dan riwayat seluruh percobaan, baik lulus maupun belum.</p>
      <div className="grid g2"><label className="f"><span>Nama lengkap</span><input type="text" autoComplete="name" value={info.name} onChange={(e) => setInfo({ ...info, name: e.target.value })} /></label>
        <label className="f"><span>NIM</span><input type="text" inputMode="numeric" value={info.nim} onChange={(e) => setInfo({ ...info, nim: e.target.value.replace(/\D/g, "") })} /></label></div>
      <div className="row"><button className="btn gold" onClick={make}>Buat sertifikat nilai</button>{made && <button className="btn gold" onClick={() => savePdf(cv.current, "Sertifikat_Nilai_Kuis_" + (info.nim || "mhs") + ".pdf", setMsg)}>Unduh PDF</button>}{made && <button className="btn ghost" onClick={png}>Unduh PNG</button>}</div>
      <p className="note" style={{ margin: 0 }}>{msg}</p></section>
      <div className="canvas-box"><canvas ref={cv} style={{ display: "block", width: "100%", aspectRatio: "1600/1131" }} /></div></div>
  );
}

function Sertifikat(props) {
  const [sub, setSub] = useState("nilai");
  return (
    <div>
      <div className="sub"><button aria-current={sub === "nilai"} onClick={() => setSub("nilai")}>Sertifikat nilai kuis</button><button aria-current={sub === "selesai"} onClick={() => setSub("selesai")}>Sertifikat penyelesaian</button></div>
      {sub === "nilai" ? <SertNilai {...props} /> : <SertSelesai {...props} />}
    </div>
  );
}

const TABS = [["beranda", "Beranda"], ["materi", "Materi"], ["lab", "Laboratorium"], ["latihan", "Latihan"], ["kuis", "Kuis"], ["penugasan", "Penugasan"], ["tutor", "Tutor AI"], ["sertifikat", "Sertifikat"]];

export default function App() {
  const [tab, setTab] = useState("beranda"), [mod, setMod] = useState(0);
  const [prog, setProg] = useState({ modDone: {}, solved: {}, attempts: 0, best: 0, passed: false, hist: [] });
  const [info, setInfo] = useState({ name: "", nim: "" });
  const go = (t) => { setTab(t); window.scrollTo(0, 0); };
  const markDone = (i) => setProg((p) => ({ ...p, modDone: { ...p.modDone, [i]: true } }));
  const markSolved = (i) => setProg((p) => ({ ...p, solved: { ...p.solved, [i]: true } }));
  const startAttempt = () => setProg((p) => ({ ...p, attempts: p.attempts + 1 }));
  const finish = (sc) => setProg((p) => ({ ...p, best: Math.max(p.best, sc), passed: p.passed || sc >= PASS, hist: [...(p.hist || []), sc] }));
  return (
    <div className="app">
      <style>{CSS}</style>
      <header className="top"><div className="wrap">
        <div className="brand"><img src={LOGO_SRC} alt="Logo UNTAG" /><div><h1>Turunan Fungsi Eksponensial dan Logaritma</h1><small>Integral Diferensial · S1 Teknik Elektro · Universitas 17 Agustus 1945 Surabaya</small></div></div>
        <nav className="tabs" aria-label="Menu utama">{TABS.map(([k, l]) => <button key={k} onClick={() => go(k)} aria-current={tab === k ? "page" : undefined}>{l}</button>)}</nav>
      </div></header>
      <main><div className="wrap">
        {tab === "beranda" && <Home prog={prog} go={go} />}
        {tab === "materi" && <Materi mod={mod} setMod={setMod} prog={prog} markDone={markDone} go={go} />}
        {tab === "lab" && <Lab />}
        {tab === "latihan" && <Latihan prog={prog} markSolved={markSolved} />}
        {tab === "kuis" && <Kuis prog={prog} startAttempt={startAttempt} finish={finish} go={go} />}
        {tab === "penugasan" && <Penugasan info={info} setInfo={setInfo} />}
        {tab === "tutor" && <Tutor mod={mod} />}
        {tab === "sertifikat" && <Sertifikat prog={prog} info={info} setInfo={setInfo} go={go} />}
      </div></main>
    </div>
  );
}

